import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    c = int(data[1])
    v = int(data[2])

    votes = list(map(int, data[3:3+v]))

    for i in range(min(v, len(votes))):
        vote = votes[i]
        if 1 <= vote <= c and (i + 1) <= n:
            print("VALID")
        else:
            print("INVALID")

if __name__ == "__main__":
    main()
